// Pure JS PBKDF2 (RFC 2898) with HMAC-SHA1.
// Depends on ./hmac.mjs providing: export function hmacSha1(key, message)
// where key/message are Uint8Array and the result is a 20-byte Uint8Array.

import { hmacSha1 } from './hmac.mjs';

/**
 * Derive a key using PBKDF2-HMAC-SHA1.
 *
 * @param {Uint8Array} password
 * @param {Uint8Array} salt
 * @param {number} iterations  iteration count (c)
 * @param {number} dkLen       desired key length in bytes
 * @returns {Uint8Array} derived key of dkLen bytes
 */
export function pbkdf2HmacSha1(password, salt, iterations, dkLen) {
  if (!(password instanceof Uint8Array) || !(salt instanceof Uint8Array)) {
    throw new TypeError('password and salt must be Uint8Array');
  }
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new TypeError('iterations must be a positive integer');
  }
  if (!Number.isInteger(dkLen) || dkLen < 1) {
    throw new TypeError('dkLen must be a positive integer');
  }

  const hLen = 20; // SHA-1 digest size
  const blockCount = Math.ceil(dkLen / hLen);
  const derived = new Uint8Array(blockCount * hLen);

  // salt || INT32_BE(i) working buffer
  const blockInput = new Uint8Array(salt.length + 4);
  blockInput.set(salt, 0);

  for (let i = 1; i <= blockCount; i++) {
    blockInput[salt.length] = (i >>> 24) & 0xff;
    blockInput[salt.length + 1] = (i >>> 16) & 0xff;
    blockInput[salt.length + 2] = (i >>> 8) & 0xff;
    blockInput[salt.length + 3] = i & 0xff;

    // U1 = HMAC(password, salt || INT32_BE(i))
    let u = hmacSha1(password, blockInput);
    const block = new Uint8Array(u);

    // Uj = HMAC(password, Uj-1); block ^= Uj
    for (let j = 1; j < iterations; j++) {
      u = hmacSha1(password, u);
      for (let k = 0; k < hLen; k++) {
        block[k] ^= u[k];
      }
    }

    derived.set(block, (i - 1) * hLen);
  }

  return derived.subarray(0, dkLen);
}

import { pbkdf2HmacSha1 } from '/output/lib/pbkdf2.mjs';

const utf8 = (s) => new TextEncoder().encode(s);
const hex = (buf) => Array.from(buf, (b) => b.toString(16).padStart(2, '0')).join('');

const cases = [
  {
    args: [utf8('password'), utf8('salt'), 1, 20],
    expected: '0c60c80f961f0e71f3a9b524af6012062fe037a6',
  },
  {
    args: [utf8('password'), utf8('salt'), 1000, 16],
    expected: '6e88be8bad7eae9d9e10aa061224034f',
  },
];

let ok = true;
for (const { args, expected } of cases) {
  const actual = hex(pbkdf2HmacSha1(...args));
  const pass = actual === expected;
  if (!pass) ok = false;
  console.log(`iters=${args[2]} dkLen=${args[3]} actual=${actual} expected=${expected} ${pass ? 'PASS' : 'FAIL'}`);
}
process.exit(ok ? 0 : 1);
